<?php

declare(strict_types=1);
namespace CetechDeliveryEngine\Tests\Unit\CustomerPolicy;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\TestCase;

/** Actual native Runtime source with declared transport-only ports in isolated PHP children. */
final class NativePolicyCartRuntimeTest extends TestCase {
	private function probe(string$mode):array{$p=dirname(__DIR__,2).'/Support/CustomerPolicy/customer-policy-cart-runtime-probe.php';$lines=[];$exit=0;exec(escapeshellarg(PHP_BINARY).' '.escapeshellarg($p).' '.escapeshellarg($mode),$lines,$exit);self::assertSame(0,$exit,implode("\n",$lines));return json_decode(implode("\n",$lines),true,16,JSON_THROW_ON_ERROR);}
	public function test_review_transport_accepts_only_closed_native_key_ticket_and_real_nonce_action():void{foreach(['review','store-review']as$mode){$r=$this->probe($mode);self::assertSame(['accepted'=>true],$r['result']);self::assertSame([['actual-key','opaque-ticket']],$r['reviews']);self::assertNull($r['refused']);}}
	#[DataProvider('refusals')]
	public function test_closed_route_refusals_never_reach_the_review_collaborator(string$mode,int$status):void{$r=$this->probe($mode);self::assertSame($status,$r['refused']);self::assertSame([],$r['reviews']);self::assertSame([],$r['calls']);}
	public static function refusals():array{return[['bad-method',405],['bad-nonce',403],['extra-field',400],['foreign-purpose',400],['bad-key',400],['disabled-review',503]];}
	public function test_default_off_native_events_do_not_read_wc_or_open_receipts():void{$r=$this->probe('off');self::assertSame(0,$r['wc_calls']);self::assertSame([],$r['calls']);self::assertSame([],$r['reviews']);}
	public function test_actual_context_mutation_service_round_trip_dispatches_the_native_invalidation_seam():void{$r=$this->probe('actual-context-roundtrip');self::assertSame([['invalidate','key'],['invalidate','key']],$r['calls']);self::assertSame(2,$r['native_session_saves']);self::assertSame(2,$r['native_total_calculations']);}
	public function test_actual_unchanged_or_off_context_commit_does_not_touch_policy_transport():void{foreach(['actual-context-unchanged','actual-context-off']as$mode){$r=$this->probe($mode);self::assertSame([],$r['calls']);self::assertSame(1,$r['native_session_saves']);self::assertSame(1,$r['native_total_calculations']);}}
	public function test_real_context_round_trip_is_two_structural_invalidations():void{$r=$this->probe('context-roundtrip');self::assertSame([['invalidate','key'],['invalidate','key']],$r['calls']);}
	public function test_real_rekey_prunes_only_the_removed_transport_and_invalidates_the_new_key():void{$r=$this->probe('rekey');self::assertSame([['forget','old'],['invalidate','new']],$r['calls']);}
	public function test_unchanged_projection_foreign_cart_and_forged_after_array_are_inert():void{foreach(['unchanged','foreign-cart','forged-after']as$mode){self::assertSame([],$this->probe($mode)['calls']);}}
	public function test_actual_empty_cart_has_a_pure_empty_witness_even_if_new_runtime_was_disabled():void{foreach(['empty','empty-off']as$mode){$r=$this->probe($mode);self::assertSame([['retire',true,'00000000-0000-4000-8000-0000000002bc']],$r['calls']);self::assertSame(['order_awaiting_payment'=>0,'store_api_draft_order'=>456],$r['native_session']);}self::assertSame([],$this->probe('not-empty')['calls']);}
	public function test_failed_actual_context_change_restores_the_exact_before_cart_before_native_persistence():void{$r=$this->probe('actual-context-failed');self::assertSame(409,$r['refused']);self::assertSame(['key'=>['quantity'=>1,'context'=>'A']],$r['native_cart']);self::assertSame(0,$r['native_session_saves']);self::assertSame(0,$r['native_total_calculations']);}
	public function test_failed_quantity_invalidation_restores_exact_old_quantity_before_totals():void{$r=$this->probe('quantity-failed');self::assertSame(409,$r['refused']);self::assertSame(['key'=>['quantity'=>1]],$r['native_cart']);self::assertSame(0,$r['native_total_calculations']);$r=$this->probe('quantity-success');self::assertNull($r['refused']);self::assertSame(['key'=>['quantity'=>2]],$r['native_cart']);self::assertSame(1,$r['native_total_calculations']);}
	public function test_remove_and_restore_pre_guards_refuse_before_destructive_transition_and_do_not_double_invalidate():void{foreach(['remove','restore']as$kind){$r=$this->probe($kind.'-failed');self::assertSame(409,$r['refused']);if($kind==='remove'){self::assertArrayHasKey('key',$r['native_cart']);self::assertSame([],$r['native_removed']);}else{self::assertSame([],$r['native_cart']);self::assertSame(['key'=>['quantity'=>1]],$r['native_removed']);}$r=$this->probe($kind.'-success');self::assertNull($r['refused']);self::assertCount(1,$r['calls']);}}
	public function test_add_failure_restores_read_only_before_snapshot_and_never_reaches_native_totals():void{$r=$this->probe('add-failed');self::assertSame(409,$r['refused']);self::assertSame(['existing'=>['quantity'=>1]],$r['native_cart']);self::assertSame(0,$r['native_total_calculations']);$r=$this->probe('add-success');self::assertNull($r['refused']);self::assertArrayHasKey('added',$r['native_cart']);self::assertSame(1,$r['native_total_calculations']);}
	public function test_incomplete_or_unconfirmed_empty_resolution_never_clears_native_checkout_pointers():void{foreach(['empty-pending','empty-failed']as$mode){$r=$this->probe($mode);self::assertSame(['order_awaiting_payment'=>123,'store_api_draft_order'=>456],$r['native_session']);}}
	public function test_native_hooks_are_registered_once_with_the_qualified_order_and_arity():void{$r=$this->probe('hooks');self::assertContains(['wp_loaded',11,1],$r['hooks']);self::assertContains(['woocommerce_add_to_cart',15,6],$r['hooks']);self::assertContains(['woocommerce_remove_cart_item',PHP_INT_MAX,2],$r['hooks']);self::assertContains(['woocommerce_restore_cart_item',PHP_INT_MAX,2],$r['hooks']);self::assertContains(['wp_loaded',12,1],$r['hooks']);self::assertContains(['cetech_de_native_cart_frame_changed',100,3],$r['hooks']);self::assertContains(['woocommerce_cart_emptied',100,1],$r['hooks']);self::assertSame(1,count(array_filter($r['hooks'],static fn($h)=>$h[0]==='cetech_de_native_cart_frame_changed')));self::assertSame(['customer_policy_review'],$r['store']);}
}
